(()=>{'use strict';
const $=s=>document.querySelector(s),form=$('[data-upgrade-form]'),parse=$('[data-upgrade-parse]'),change=$('[data-upgrade-change]');if(!form)return;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slots=['cpu','board','gpu','ram','ssd','hdd','psu','case'];let records=[],baseline=null,current=null,phases=[],loaded=false,inventoryDirty=false;
const slotLabels={cpu:'Processor',board:'Motherboard',gpu:'Graphics card',ram:'Memory kit',ssd:'SSD',hdd:'Hard drive',psu:'Power supply',case:'Case',storage:'Storage'};
const displayName=p=>p.name.toLowerCase().startsWith(p.brand.toLowerCase()+' ')?p.name:p.brand+' '+p.name;
const status=text=>$('[data-upgrade-status]').textContent=text;
const emptyParts=()=>Object.fromEntries(slots.map(s=>[s,[]]));
const copy=p=>Object.fromEntries(slots.map(s=>[s,[...(p[s]||[])]]));
const selections=()=>Object.fromEntries(slots.map(s=>[s,records.filter(p=>p.id===form.elements[s].value&&p.cat===s)]));
function invalidate(){if(current){inventoryDirty=true;status('Inventory or planning inputs changed. Create the reuse plan again before checking, exporting or opening it.')}}
function requireCurrent(){if(!current)throw Error('Create the existing-PC plan first.');if(inventoryDirty)throw Error('Create the reuse plan again to use your changed inventory and planning inputs.')}
for(const event of ['input','change'])form.addEventListener(event,e=>{if(slots.includes(e.target.name)||['region','budget','goal'].includes(e.target.name))invalidate()});
try{const initial=new URL(location.href).searchParams.get('region')||document.documentElement.dataset.region||localStorage.getItem('pcp-region');if(['CA','US'].includes(initial))form.elements.region.value=initial}catch{}
function renderChecks(parts,target){const report=PCP_BUILD_RULES.createReadiness({parts,requirements:{workload:form.elements.goal.value}}),groups={failed:'Documented conflicts',passed:'Documented checks passed','needs-verification':'Needs verification',unperformed:'Checks this tool cannot perform'};target.innerHTML=`<h3>Compatibility after this selection</h3><p>${esc(report.summary)}</p>${report.missing.length?`<p><strong>Still missing:</strong> ${report.missing.map(s=>esc(slotLabels[s]||s)).join(', ')}.</p>`:''}${Object.entries(groups).filter(([state])=>report.counts[state]).map(([state,label])=>`<details ${state==='failed'?'open':''}><summary>${esc(label)} · ${report.counts[state]}</summary><ul>${report.checks.filter(c=>c.state===state).map(c=>`<li><strong class="program-state-${c.state}">${esc(c.title)}</strong><p>${esc(c.reason)}</p><p>${esc(c.next||'')}</p>${c.sources.length?`<ul>${c.sources.map(s=>`<li><a href="${esc(typeof s==='string'?s:s.url)}">${esc(typeof s==='string'?'Source documentation':s.publisher||'Source documentation')}</a></li>`).join('')}</ul>`:''}</li>`).join('')}</ul></details>`).join('')}`;return report}
function replacementChoices(){const slot=change.elements.slot.value;change.elements.replacement.innerHTML='<option value="">Choose an exact model</option>'+records.filter(p=>p.cat===slot).map(p=>`<option value="${esc(p.id)}">${esc(displayName(p))}</option>`).join('');change.elements.replacement.disabled=!loaded}
function candidate(){requireCurrent();const slot=change.elements.slot.value,p=records.find(p=>p.id===change.elements.replacement.value&&p.cat===slot);if(!p)throw Error('Choose an exact replacement model.');const next=copy(current);next[slot]=[p];return{slot,p,next}}
function loadOwnedContext(){const query=new URL(location.href).searchParams.get('owned');if(!query)return;const ids=query.split(',');if(ids.length>8||ids.some(id=>!/^[a-zA-Z0-9_-]{1,120}$/.test(id))){status('Shared inventory is invalid. Select your exact installed parts manually.');return}const found=ids.map(id=>records.find(p=>p.id===id&&slots.includes(p.cat)));if(found.some(p=>!p)||new Set(found.map(p=>p.cat)).size!==found.length){status('Shared inventory has unknown or repeated categories. Confirm the installed parts manually.');return}for(const p of found)form.elements[p.cat].value=p.id;status('Exact part selections carried from your comparison. Confirm they are installed, then create the reuse plan.');}
fetch('/data/program-parts.json').then(r=>{if(!r.ok)throw Error('Part choices could not load.');return r.json()}).then(data=>{if(!Array.isArray(data)||data.length>5000||data.some(p=>!p||typeof p.id!=='string'||!/^[a-zA-Z0-9_-]{1,120}$/.test(p.id)||typeof p.name!=='string'||!p.name.trim()||![...slots,'fan'].includes(p.cat))||new Set(data.map(p=>p.id)).size!==data.length)throw Error('Part choices have an invalid or duplicate identity.');records=data;loaded=true;for(const s of slots){form.elements[s].innerHTML='<option value="">Not selected / unknown</option>'+records.filter(p=>p.cat===s).map(p=>`<option value="${esc(p.id)}">${esc(displayName(p))}</option>`).join('');form.elements[s].disabled=false}replacementChoices();loadOwnedContext();$('[data-upgrade-loading]').textContent='Select exact installed parts. Older parts remain available; age alone is not a reason to replace them.'}).catch(e=>{$('[data-upgrade-loading]').textContent=e.message+' Use the hardware catalog or retry the page.';status(e.message)});
parse.addEventListener('submit',e=>{e.preventDefault();const box=$('[data-upgrade-matches]');try{if(!loaded)throw Error('Wait for part choices to load.');const parsed=PCP_PLANNERS.parsePartsList(parse.elements.parts.value,records);box.replaceChildren();for(const item of parsed){const row=document.createElement('div');row.className='program-match';const label=document.createElement('label');label.textContent=item.line+' — '+item.status.replaceAll('_',' ');const select=document.createElement('select');select.setAttribute('aria-label','Confirm model for '+item.line);select.innerHTML='<option value="">Leave unresolved</option>'+item.candidates.map(c=>`<option value="${esc(c.id)}">${esc(c.brand+' '+c.name)} (${esc(c.category)})</option>`).join('');label.append(select);const button=document.createElement('button');button.type='button';button.className='button secondary';button.textContent='Confirm this model';button.addEventListener('click',()=>{const p=records.find(p=>p.id===select.value);if(!p||!slots.includes(p.cat)){status('Choose a model supported by this inventory.');return}form.elements[p.cat].value=p.id;form.elements[p.cat].dispatchEvent(new Event('change',{bubbles:true}));invalidate();row.dataset.confirmed='true';button.textContent='Confirmed';status('Confirmed '+p.name+'. Review the inventory, then create the plan.');});row.append(label,button);box.append(row)}if(!parsed.length)box.textContent='Paste one component per line.'}catch(err){box.textContent=err.message}});
form.addEventListener('submit',e=>{e.preventDefault();if(!loaded){status('Part choices are still unavailable.');return}baseline=selections();current=copy(baseline);phases=[];inventoryDirty=false;const out=$('[data-upgrade-result]'),report=PCP_BUILD_RULES.createReadiness({parts:current});const rows=slots.map(s=>{const p=current[s][0];return`<tr><th scope="row">${esc(slotLabels[s]||s)}</th><td>${p?`<a href="/learn/${esc(p.id)}.html">${esc(p.name)}</a>`:'Unknown / not selected'}</td><td>${p?'Keep unless the workload evidence justifies a change; verify support for a swap.':'Verify existing hardware before choosing a replacement.'}</td></tr>`}).join('');out.innerHTML=`<h2>Keep, replace or verify</h2><p>Doing nothing is a valid option. There is no demonstrated upgrade gain in this plan without comparable workload measurements.</p><div class="table-scroll"><table class="program-table"><caption>Your confirmed starting inventory</caption><thead><tr><th scope="col">Part</th><th scope="col">Exact selection</th><th scope="col">Decision basis</th></tr></thead><tbody>${rows}</tbody></table></div><p><strong>New spending is unknown.</strong> Existing-part value is not counted as a new purchase. Obtain complete exact quotes before comparing a platform replacement with a single-part upgrade.</p><div data-upgrade-readiness></div>`;renderChecks(current,$('[data-upgrade-readiness]'));const symptom=form.elements.symptom.value;if(symptom!=='none')out.insertAdjacentHTML('afterbegin',`<p class="program-note">Start with <a href="/troubleshooting/?symptom=${esc(symptom)}">the safe checks for your symptom</a>. A configuration fix may avoid a purchase.</p>`);$('[data-upgrade-phases]').replaceChildren();status('Reuse plan created; '+report.counts['needs-verification']+' checks need evidence.');window.PCP_EVENTS?.track('upgrade_result_generated',{page_type:'upgrade',category:form.elements.goal.value})});
change.elements.slot.addEventListener('change',replacementChoices);
change.addEventListener('submit',e=>{e.preventDefault();try{const c=candidate();const target=$('[data-upgrade-change-result]');renderChecks(c.next,target);target.insertAdjacentHTML('afterbegin',`<h3>Alternative: ${esc(c.p.name)}</h3><p>Compare the complete configuration, including required support, cooling, memory, connectors and purchase costs. No measured uplift is available from this selection alone.</p>`);status('Alternative checked without changing the current phase.')}catch(err){status(err.message)}});
$('[data-upgrade-phase]').addEventListener('click',()=>{try{if(phases.length>=25)throw Error('Export or start a new plan before adding more than 25 phases.');const c=candidate();current=c.next;const report=PCP_BUILD_RULES.createReadiness({parts:current});phases.push({slot:c.slot,productId:c.p.id,parts:Object.fromEntries(slots.map(s=>[s,current[s].map(p=>p.id)])),checks:report.checks});const node=document.createElement('section');node.className='program-match';node.innerHTML=`<h3>Phase ${phases.length}: replace ${esc(slotLabels[c.slot]||c.slot)} with ${esc(c.p.name)}</h3><div></div>`;renderChecks(current,node.querySelector('div'));renderChecks(current,$('[data-upgrade-readiness]'));$('[data-upgrade-phases]').append(node);status('Phase saved to this open plan. Export to keep it. '+report.counts.failed+' documented conflicts; '+report.counts['needs-verification']+' checks need evidence.')}catch(err){status(err.message)}});
$('[data-upgrade-builder]').addEventListener('click',()=>{try{requireCurrent();const owned=slots.flatMap(s=>current[s].filter(p=>baseline[s].some(b=>b.id===p.id)).map(p=>p.id)),revision=PCP_BUILD_RULES.normalizeRevision({parts:current,owned,region:form.elements.region.value,budget:form.elements.budget.value,requirements:{workload:['gaming','creator'].includes(form.elements.goal.value)?form.elements.goal.value:'general'}},records).revision,url=new URL(PCP_BUILD_RULES.buildURL(revision,location.origin));location.href=url.pathname+url.search}catch(err){status(err.message)}});
$('[data-upgrade-export]').addEventListener('click',()=>{try{requireCurrent()}catch(err){status(err.message);return}const data={schema:'pcp-upgrade-v1',region:form.elements.region.value,currency:form.elements.region.value==='US'?'USD':'CAD',budget:PCP_BUILD_RULES.validAmount(form.elements.budget.value),baseline:Object.fromEntries(slots.map(s=>[s,baseline[s].map(p=>p.id)])),parts:Object.fromEntries(slots.map(s=>[s,current[s].map(p=>p.id)])),phases,limitations:['Manual inventory; one exact entry per component category; exact support still needs verification.','No measured uplift or complete checked cost is available.']},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pc-upgrade-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);status('Plan exported. It contains selections and phases, not private notes.');window.PCP_EVENTS?.track('upgrade_export',{page_type:'upgrade'})});
})();
